use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-arithmetic-leaves";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn med(mut v:Vec<f64>)->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("capture/result.json"))["status"],"complete");for(p,h)in read(r.join("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut seen:BTreeSet<String>=serde_json::from_value(read(r.join("prior-proofs.json"))).unwrap();assert_eq!(seen.len(),7177);let mut inventory=BTreeMap::new();let mut rows=Vec::new();let mut graphs=Vec::new();let mut raw=BTreeMap::new();let mut sdk=0;
 for phase in ["preflight","capture"]{let jobs=read(r.join(if phase=="preflight"{"preflight-jobs.json"}else{"jobs.json"}));for job in jobs.as_array().unwrap(){let name=job["name"].as_str().unwrap();let out=Path::new(job["output"].as_str().unwrap());let proof=out.join("0.proof");let public=out.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(&public),job["public_sha256"].as_str().unwrap());assert!(seen.insert(hash(&proof)));for p in [proof,public]{inventory.insert(p.display().to_string(),hash(p));}let log=fs::read_to_string(r.join(phase).join(name).join("stdout.log")).unwrap();let verify=fs::read_to_string(r.join(format!("{phase}/verify-{name}/stdout.log"))).unwrap();assert!(verify.contains("verified 1 distinct proofs across 1 pinned keys"));let summary:Value=serde_json::from_str(log.lines().find_map(|s|s.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],job["rounds"]);sdk+=summary["rounds"].as_u64().unwrap()+3;let samples:Vec<f64>=log.lines().filter_map(|s|s.strip_prefix("SAMPLE ")).map(|s|serde_json::from_str::<Value>(s).unwrap()["ms"].as_f64().unwrap()).collect();assert_eq!(samples.len(),job["rounds"].as_u64().unwrap()as usize);rows.push(json!({"phase":phase,"job":job,"median_ms":med(samples.clone()),"samples_ms":samples,"summary":summary}));for line in log.lines().filter_map(|s|s.strip_prefix("GRAPH ")){let g:Value=serde_json::from_str(line).unwrap();let file=g["file"].as_str().unwrap();let bytes=fs::read(file).unwrap();assert_eq!(bytes.len()%80,0);let mut kinds=BTreeMap::new();for e in bytes.chunks_exact(80){let kind=u64::from_le_bytes(e[16..24].try_into().unwrap());*kinds.entry(kind).or_insert(0)+=1;}if job["mode"]=="on"{assert_eq!(kinds.get(&6),None);assert_eq!(kinds.get(&1),Some(&1));}raw.insert(file.to_string(),hash(file));let packed=Path::new(file).with_extension("events.gz");let result=Command::new("gzip").args(["-c","--",file]).output().unwrap();assert!(result.status.success());fs::write(&packed,result.stdout).unwrap();graphs.push(json!({"phase":phase,"job":job,"metadata":g,"event_kinds":kinds,"whole_A_query_missing":job["mode"]=="on","attribution_valid":false,"packed":packed,"packed_sha256":hash(&packed)}));}}}
 assert_eq!(sdk,652);assert_eq!(inventory.len(),56);assert_eq!(seen.len(),7205);save(r.join("proof-inventory.json"),&json!(inventory));save(r.join("initial-rows.json"),&json!(rows));save(r.join("initial-graphs.json"),&json!(graphs));save(r.join("raw-local-sha256.json"),&json!(raw));save(r.join("initial-analysis.json"),&json!({"status":"all captures retained; source attribution incomplete","reason":"Outer A-query hook targeted msm_affine::msm, but the canonical-wire prover calls msm_canonical. The strict decoder correctly rejected absent kind6. Do not infer grouping/query attribution from these graphs.","SDK_requests":652,"independent_gnark_exports":28,"proof_public_members":56,"next_prior_count":7205,"capture_failure":false,"analysis_failure":true,"prior7177":true,"corrected_source_required":true,"adopted":false,"goal_achieved":false}));println!("Retained ALL652SDK28verifiedexports;prior7205; originaltraceattributioninvalid, no timingexclusions");}
